*	Low-level VGA Board Interface Routines*	Copyright 1994, Sequential Systems*	Written by Jawaid Bazyar*	mcopy	vgalow.mac	case	onWR_CMD	gequ	$E0C0B0WR_DATA	gequ	$E0C0B1RD_DATA	gequ	$E0C0B2HANDSHAKE	gequ	$E0C0B8VM_40x25	gequ	$00	; GS RGB compatible modesVM_80x25	gequ	$02VM_320x200	gequ	$13VM_640x400	gequ	$61VM_800x600	gequ	$54	; VGA/SVGA-only modesVM_1024x768	gequ	$56VM_132x60	gequ	$4FVM_132x43	gequ	$51VM_640x480	gequ	$53SH_NONE	gequ	%00000000SH_SHR	gequ	%00000001SH_HIRES	gequ	%00000010SH_TEXT	gequ	%00000100SH_DBL_HIRES	gequ	%00001000SH_TEXT_80	gequ	%00010000* Command byte codesCMD_Status	gequ	$00CMD_SetMode	gequ	$01CMD_UploadData	gequ	$02CMD_ScrollScreen gequ $03CMD_ScreenOff	gequ	$04CMD_ScreenOn	gequ	$05CMD_SetPalette	gequ	$06CMD_SetPaletteEntry gequ $07CMD_SetBorder	gequ	$08CMD_RunCode	gequ	$09CMD_ClearScreen gequ	$0ACMD_SetShadow	gequ	$0BCMD_SetVGAReg	gequ	$0CCMD_GetVGAReg	gequ	$0DCMD_SetUserMode gequ	$0E* Upload code/data flagsFL_Z180	gequ	$00FL_VGA	gequ	$01* Get VGA Status / Existence_GetStatus	STARTretv	equ	1tptr	equ	retv+2	sub	(4:status_rec),6	               php	sei               lda	<status_rec	sta	<tptr	lda	<status_rec+2	sta	<tptr+2	lda	#0	sta	<retv	short	m	lda	#CMD_Status	sta	>WR_CMD               ldx	#$FFFFlp1	lda	>HANDSHAKE	cmp	#$01	; are they ready yet?	beq	gothshake               dex	bne	lp1	long	m	lda	#-1	sta	<retv	bra	goaway		longa	offgothshake	anop	ldx	#5	lda	>RD_DATA	; dummy readlp2	lda	>RD_DATA	sta	[<status_rec]	inc	<status_rec		bne	lp22	inc	<status_rec+1lp22	dex	bne	lp2	               lda	[<tptr]	cmp	#'G'	bne	err	ldy	#1	lda	[<tptr],y	cmp	#'S'	bne	err	iny	lda	[<tptr],y	cmp	#'V'	bne	err	iny	lda	[<tptr],y	cmp	#'G'	bne	err	iny	lda	[<tptr],y	cmp	#'A'	beq	noerr	err	lda	#$FF	sta	<retv	sta	<retv+1               bra	exitpointnoerr	anop	lda	#0	xba	lda	>RD_DATA	tax	sta	[<status_rec]	inc	<status_rec	bne	lp3	inc	<status_rec+1lp3	anop	lda	>RD_DATA	sta	[<status_rec]	inc	<status_rec	bne	lp33	inc	<status_rec+1lp33	dex*	bpl	lp3	bne	lp3exitpoint	long	mgoaway	plp	ret	2:retv	END* should take mode to set & shadow bits in a parameter block_ClearScreen	START	sub	(4:length,4:addr,2:color),0	php	sei	lda	#CMD_ClearScreen	jsr	_WriteCmd	jsr	WaitHSOn	lda	<color	jsr	_WriteData	lda	<addr	jsr	_WriteData	lda	<addr+1	jsr	_WriteData	lda	<addr+2     	jsr	_WriteData	lda	<length	jsr	_WriteData	lda	<length+1	jsr	_WriteData	lda	<length+2	jsr	_WriteData	jsr	WaitHSOff               jsr	WaitHSDone	plp	ret	END_RunCode	START	sub	(2:zaddr,2:bbr,2:cbar,2:cbr),0	php	sei	lda	#CMD_RunCode	jsr	_WriteCmd	jsr	WaitHSOn	lda	<cbr	jsr	_WriteData	lda	<cbar	jsr	_WriteData	lda	<bbr	jsr	_WriteData	lda	<zaddr	jsr	_WriteData	lda	<zaddr+1	jsr	_WriteData	jsr	WaitHSOff               jsr	WaitHSDone	plp	ret	END                _ScrollScreen	START	sub	(4:length,4:dst,4:src),0	php	sei	lda	#CMD_ScrollScreen	jsr	_WriteCmd	jsr	WaitHSOn	lda	<src	jsr	_WriteData	lda	<src+1	jsr	_WriteData	lda	<src+2	jsr	_WriteData	lda	<dst	jsr	_WriteData	lda	<dst+1	jsr	_WriteData	lda	<dst+2	jsr	_WriteData	lda	<length	jsr	_WriteData	lda	<length+1	jsr	_WriteData	lda	<length+2   	jsr	_WriteData                                          plp	jsr	WaitHSOff	; be sure they finished the DMA	jsr	WaitHSDone	; wait for them to finish the cmd	ret                	END_SetMode	START	sub	(2:shadow,2:mode),0	php	sei	lda	#CMD_SetMode	jsr	_WriteCmd	jsr	WaitHSOn	lda	<mode	jsr	_WriteData	lda	<shadow	jsr	_WriteData	jsr	WaitHSOff	               jsr	WaitHSDone	plp	ret		END_SetShadow	START	sub	(2:shadow),0	php	sei	lda	#CMD_SetShadow	jsr	_WriteCmd	jsr	WaitHSOn	lda	<shadow	jsr	_WriteData	jsr	WaitHSOff		plp	ret		END_SetPaletteEntry START	sub	(4:rgb,2:entry),0	php	sei	lda	#CMD_SetPaletteEntry	jsr	_WriteCmd	jsr	WaitHSOn	lda	<entry	jsr	_WriteData	lda	<rgb	jsr	_WriteData	lda	<rgb+1	jsr	_WriteData	lda	<rgb+2	jsr	_WriteData	jsr	WaitHSOff		plp	ret	END_SetPalette	START	sub	(4:palptr),0	php	sei               lda	#CMD_SetPalette	jsr	_WriteCmd	jsr	WaitHSOn	lda	<palptr	jsr	_WriteCmd	lda	<palptr+1	jsr	_WriteCmd	lda	<palptr+2	jsr	_WriteCmd	jsr	WaitHSOff	jsr	WaitHSOn		ldy	#0lp2	lda	[<palptr],y	jsr	_WriteData	iny	cpy	#768	bne	lp2	jsr	WaitHSOff	plp	ret	END_SetUserMode	START	sub	(4:regsptr),0	php	sei	lda	#CMD_SetUserMode	jsr	_WriteCmd	jsr	WaitHSOn	ldy	#0lp	lda	[<regsptr],y	sta	>WR_DATA	iny	iny	cpy	#84	bcc	lp	jsr	WaitHSOff	plp	ret	END_SetBorder	START	sub	(2:color),0	php	sei	lda	#CMD_SetBorder	jsr	_WriteCmd	jsr	WaitHSOn	lda	<color	jsr	_WriteCmd	               jsr	WaitHSOff	               plp	ret	END_SetVGAReg	START	sub	(2:val,2:reg,2:idxval,2:idxreg),0	php	sei	lda	#CMD_SetVGAReg	jsr	_WriteCmd	jsr	WaitHSOn	lda	<idxreg	jsr	_WriteCmd	lda	<idxreg+1	jsr	_WriteCmd	lda	<idxval	jsr	_WriteCmd	lda	<reg	jsr	_WriteCmd	lda	<reg+1	jsr	_WriteCmd		lda	<val	jsr	_WriteCmd	jsr	WaitHSOff	plp	ret	END_GetVGAReg	STARTval	equ	1	sub	(2:reg,2:idxval,2:idxreg),2	php	sei	lda	#CMD_GetVGAReg	jsr	_WriteCmd	jsr	WaitHSOn	lda	<idxreg	jsr	_WriteCmd	lda	<idxreg+1	jsr	_WriteCmd	lda	<idxval	jsr	_WriteCmd	lda	<reg	jsr	_WriteCmd	lda	<reg+1	jsr	_WriteCmd		jsr	WaitHSOff	jsr	WaitHSOn	lda	>RD_DATA	; dummy read	lda	>RD_DATA	sta	<val               jsr	WaitHSOff	plp	ret	2:val	END_ScreenOn	START	sub	(0:foo),0	php	sei	lda	#CMD_ScreenOn	jsr	_WriteCmd	               plp	ret	END_ScreenOff	START	sub	(0:foo),0	lda	#CMD_ScreenOff	jsr	_WriteCmd	ret	END_UploadData	STARTbanks	equ	1old_hshake	equ	3oddbyte	equ	5	sub (4:src_addr,4:length,4:dst_addr,2:flag),6	stz	<oddbyte	php	sei               lda	#CMD_UploadData	jsr	_WriteCmd	jsr	WaitHSOn;	jsr	_WriteData	; false access	lda	<flag	jsr	_WriteData; offset into video memory to put this data	lda	<dst_addr	jsr	_WriteData	lda	<dst_addr+1	jsr	_WriteData	lda	<dst_addr+2	jsr	_WriteData; length of data that we are sending	lda	<length	jsr	_WriteData	lda	<length+1	jsr	_WriteData	lda	<length+2	jsr	_WriteData; pass address in IIGS memory of data to send the card	lda	<src_addr	jsr	_WriteData	lda	<src_addr+1	jsr	_WriteData	lda	<src_addr+2	jsr	_WriteData	jsr	WaitHSOff	lda	<length+2	and	#$00FF	sta	<banks               beq	lp2headlp0	anop	jsr	WaitHSOn	ldy	#256	; Do 256 pages == 1 banklp1	ldx	<src_addr	lda	<src_addr+2	jsr	WritePage	inc	<src_addr+1	; increment the page #	dey	bne	lp1	jsr	WaitHSOff		dec	<banks	bne	lp0lp2head	anop	jsr	WaitHSOn		lda	<length	and	#1	sta	<oddbyte	lda	<length	and	#$FFFE	sta	<length	stz	<length+2	; we did all the banks	lda	<length+1	; get # of pages to transmit	beq	lp21	tay		; do that many pageslp333	ldx	<src_addr	lda	<src_addr+2	jsr	WritePage	inc	<src_addr+1	dey	bne	lp333	stz	<length+1	; less than one page* Is there now less than a page worth of data left?lp21	lda	<length	beq	lastcheck	; no, but might be one byte...	ldy	#0lp2	lda	[src_addr],y	sta	>WR_DATA	iny	iny	cpy	<length	bne	lp2* Checks to see if there's one last byte of data to transmit.lastcheck	lda	<oddbyte	beq	doneit	short	m	lda	[src_addr],y	sta	>WR_DATA	long	mdoneit	jsr	WaitHSOff	               plp	ret	END	* Mega-low-level routines. Byte-wise I/O to/from the VGA card* takes byte to write in accumulator* does not return until the Z180 has modified the data status latch* The Z180 operates in three possible polled I/O data modes.* a) The Z180 has INT1 turned on. This is used for command block data.*    each byte in a command block will interrupt the Z180.* b) The Z180 has INT1 turned off. This is used for large data uploads;*    each byte in a data block will simply set the CTS1 pin on the Z180*    and the Z180 will know from reading the CTS1 pin that data is present*    in the latch.* c) The Z180 will have a DMA transfer set up for large block transfers.*    The IIGS simply stuffs data into WR_DATA as fast as possible, and*    the Z180 goes SLAM SLAM SLAM._FalseRead	START		sep	#$30	longa	off	longi	off	lda	>WR_CMD	rep	#$30	longa	on	longi	on	rts               END_WriteByte	START		tax	sep	#$30	longa	off	longi	off;	lda	>HANDSHAKE	tay	txa	sta	>WR_DATA* this interfaces with the routine send_handshake in the Z180 code.* file interp_a.a. When the RDY support in the PAL is done, remove this* code and remove calls to send_handshake	tyalp	cmp	>HANDSHAKE	beq	lp	rep	#$30	longa	on	longi	on	rts	END_WriteCmd	START	short	m	sta	>WR_CMD               long	m	rts	END_WriteData	START	short	m	sta	>WR_DATA	long	m	rts	ENDWaitHSOn	START	lda	#1	short	mlp	cmp	>HANDSHAKE	bne	lp	long	m	rts	ENDWaitHSDone	START	short	mlp	lda	>HANDSHAKE	cmp	#$A5	beq	goner	cmp	#$A6	bne	lpgoner	long	m	rts	ENDWaitHSOff	START	lda	#0	short	mlp	cmp	>HANDSHAKE	bne	lp	long	m	rts	ENDlongdelay	START	ldx	#$100lp	dex	bne	lp	rts	END* A = source bank, X = starting offset in source bankWritePage	START	phb	short	m	pha	plb	long	m	phd	lda	#$C000	tcd	lda	|$00,x	sta	<WR_DATA	lda	|$02,x	sta	<WR_DATA	lda	|$04,x	sta	<WR_DATA	lda	|$06,x	sta	<WR_DATA	lda	|$08,x	sta	<WR_DATA	lda	|$0A,x	sta	<WR_DATA	lda	|$0C,x	sta	<WR_DATA	lda	|$0E,x	sta	<WR_DATA	lda	|$10,x	sta	<WR_DATA	lda	|$12,x	sta	<WR_DATA	lda	|$14,x	sta	<WR_DATA	lda	|$16,x	sta	<WR_DATA	lda	|$18,x	sta	<WR_DATA	lda	|$1A,x	sta	<WR_DATA	lda	|$1C,x	sta	<WR_DATA	lda	|$1E,x	sta	<WR_DATA	lda	|$20,x	sta	<WR_DATA	lda	|$22,x	sta	<WR_DATA	lda	|$24,x	sta	<WR_DATA	lda	|$26,x	sta	<WR_DATA	lda	|$28,x	sta	<WR_DATA	lda	|$2A,x	sta	<WR_DATA	lda	|$2C,x	sta	<WR_DATA	lda	|$2E,x	sta	<WR_DATA                        	lda	|$30,x	sta	<WR_DATA	lda	|$32,x	sta	<WR_DATA	lda	|$34,x	sta	<WR_DATA	lda	|$36,x	sta	<WR_DATA	lda	|$38,x	sta	<WR_DATA	lda	|$3A,x	sta	<WR_DATA	lda	|$3C,x	sta	<WR_DATA	lda	|$3E,x	sta	<WR_DATA                        	lda	|$40,x	sta	<WR_DATA	lda	|$42,x	sta	<WR_DATA	lda	|$44,x	sta	<WR_DATA	lda	|$46,x	sta	<WR_DATA	lda	|$48,x	sta	<WR_DATA	lda	|$4A,x	sta	<WR_DATA	lda	|$4C,x	sta	<WR_DATA	lda	|$4E,x	sta	<WR_DATA                        	lda	|$50,x	sta	<WR_DATA	lda	|$52,x	sta	<WR_DATA	lda	|$54,x	sta	<WR_DATA	lda	|$56,x	sta	<WR_DATA	lda	|$58,x	sta	<WR_DATA	lda	|$5A,x	sta	<WR_DATA	lda	|$5C,x	sta	<WR_DATA	lda	|$5E,x	sta	<WR_DATA                        	lda	|$60,x	sta	<WR_DATA	lda	|$62,x	sta	<WR_DATA	lda	|$64,x	sta	<WR_DATA	lda	|$66,x	sta	<WR_DATA	lda	|$68,x	sta	<WR_DATA	lda	|$6A,x	sta	<WR_DATA	lda	|$6C,x	sta	<WR_DATA	lda	|$6E,x	sta	<WR_DATA                       	lda	|$70,x	sta	<WR_DATA	lda	|$72,x	sta	<WR_DATA	lda	|$74,x	sta	<WR_DATA	lda	|$76,x	sta	<WR_DATA	lda	|$78,x	sta	<WR_DATA	lda	|$7A,x	sta	<WR_DATA	lda	|$7C,x	sta	<WR_DATA	lda	|$7E,x	sta	<WR_DATA                       	lda	|$80,x	sta	<WR_DATA	lda	|$82,x	sta	<WR_DATA	lda	|$84,x	sta	<WR_DATA	lda	|$86,x	sta	<WR_DATA	lda	|$88,x	sta	<WR_DATA	lda	|$8A,x	sta	<WR_DATA	lda	|$8C,x	sta	<WR_DATA	lda	|$8E,x	sta	<WR_DATA                       	lda	|$90,x	sta	<WR_DATA	lda	|$92,x	sta	<WR_DATA	lda	|$94,x	sta	<WR_DATA	lda	|$96,x	sta	<WR_DATA	lda	|$98,x	sta	<WR_DATA	lda	|$9A,x	sta	<WR_DATA	lda	|$9C,x	sta	<WR_DATA	lda	|$9E,x	sta	<WR_DATA                       	lda	|$A0,x	sta	<WR_DATA	lda	|$A2,x	sta	<WR_DATA	lda	|$A4,x	sta	<WR_DATA	lda	|$A6,x	sta	<WR_DATA	lda	|$A8,x	sta	<WR_DATA	lda	|$AA,x	sta	<WR_DATA	lda	|$AC,x	sta	<WR_DATA	lda	|$AE,x	sta	<WR_DATA                        	lda	|$B0,x	sta	<WR_DATA	lda	|$B2,x	sta	<WR_DATA	lda	|$B4,x	sta	<WR_DATA	lda	|$B6,x	sta	<WR_DATA	lda	|$B8,x	sta	<WR_DATA	lda	|$BA,x	sta	<WR_DATA	lda	|$BC,x	sta	<WR_DATA	lda	|$BE,x	sta	<WR_DATA                        	lda	|$C0,x	sta	<WR_DATA	lda	|$C2,x	sta	<WR_DATA	lda	|$C4,x	sta	<WR_DATA	lda	|$C6,x	sta	<WR_DATA	lda	|$C8,x	sta	<WR_DATA	lda	|$CA,x	sta	<WR_DATA	lda	|$CC,x	sta	<WR_DATA	lda	|$CE,x	sta	<WR_DATA                        	lda	|$D0,x	sta	<WR_DATA	lda	|$D2,x	sta	<WR_DATA	lda	|$D4,x	sta	<WR_DATA	lda	|$D6,x	sta	<WR_DATA	lda	|$D8,x	sta	<WR_DATA	lda	|$DA,x	sta	<WR_DATA	lda	|$DC,x	sta	<WR_DATA	lda	|$DE,x	sta	<WR_DATA                        	lda	|$E0,x	sta	<WR_DATA	lda	|$E2,x	sta	<WR_DATA	lda	|$E4,x	sta	<WR_DATA	lda	|$E6,x	sta	<WR_DATA	lda	|$E8,x	sta	<WR_DATA	lda	|$EA,x	sta	<WR_DATA	lda	|$EC,x	sta	<WR_DATA	lda	|$EE,x	sta	<WR_DATA                        	lda	|$F0,x	sta	<WR_DATA	lda	|$F2,x	sta	<WR_DATA	lda	|$F4,x	sta	<WR_DATA	lda	|$F6,x	sta	<WR_DATA	lda	|$F8,x	sta	<WR_DATA	lda	|$FA,x	sta	<WR_DATA	lda	|$FC,x	sta	<WR_DATA	lda	|$FE,x	sta	<WR_DATA	PLD	PLB	rts	END